/** Only map assets generated by scripts/optimize-realisation-images.mjs. */
export function responsiveRealisation(src: string, sizes = '(max-width: 639px) 100vw, (max-width: 1023px) 50vw, 320px') {
  const match = src.match(/^\/images\/realisations-20261010\/([^/]+)\.(?:png|jpg|jpeg)$/i);
  if (!match) return { src };
  const base = `/images/optimized-realisations/${match[1]}`;
  return { src: `${base}-960.webp`, srcSet: `${base}-480.webp 480w, ${base}-960.webp 960w`, sizes };
}
